hints.tier2Scaffold:
WITH monthly AS (
  SELECT strftime('%Y-%m', enrolled_on) AS month, COUNT(*) AS enrolled
  FROM patients GROUP BY month
)
SELECT month, enrolled, SUM(enrolled) OVER (ORDER BY month) AS total_to_date
FROM monthly ORDER BY month;

